pub struct Item { pub sku: String, pub qty: u32 }
pub struct Inventory { items: Vec<Item> }

impl Inventory {
    pub fn restock(&mut self, sku: &str, qty: u32) -> bool {
        for item in self.items.iter_mut() {
            if item.sku == sku {
                item.qty += qty;
                return true;
            }
        }
        false
    }

    pub fn sell(&mut self, sku: &str, qty: u32) -> Result<(), SellError> {
        for item in self.items.iter_mut() {
            if item.sku == sku {
                if item.qty < qty {
                    return Err(SellError::Insufficient);
                }
                item.qty -= qty;
                return Ok(());
            }
        }
        Err(SellError::UnknownSku)
    }
}

